#[test]
fn review_library_context_measurement_and_truncation() {
    let tmp = tempfile::tempdir().unwrap();
    let real = coach_services::CoachService::open(tmp.path()).unwrap();
    real.save_settings(json!({"player_id":"p","player_name":"Player","provider":"none","replay_folder":"","auto_import":false})).unwrap();
    let keys: [&str; 24] = [
        "score",
        "goals",
        "assists",
        "saves",
        "shots",
        "touches",
        "avg_boost",
        "low_boost_pct",
        "avg_speed",
        "supersonic_boost_seconds",
        "defensive_half_pct",
        "ahead_ball_pct",
        "avg_ball_distance",
        "tracked_seconds",
        "boost_active_at_supersonic_speed_s",
        "time_at_or_above_supersonic_threshold_s",
        "time_at_or_above_supersonic_threshold_pct",
        "boost_tracked_seconds",
        "speed_tracked_seconds",
        "position_tracked_seconds",
        "car_ball_tracked_seconds",
        "total_boost",
        "small_pad_pickups",
        "large_pad_pickups",
    ];
    for i in 0..60 {
        let mut r = replay();
        r["summary"]["id"] = json!(format!("synthetic-{i:03}"));
        r["summary"]["mode"] = json!(["1v1", "2v2", "3v3"][i % 3]);
        r["summary"]["played_at"] = json!(format!("2026-10-{:02}T00:00:00Z", i % 28 + 1));
        r["metrics"]=json!(keys.iter().enumerate().map(|(n,k)|json!({"player_id":"p","key":k,"value":31.4444444444+n as f64,"numerator":9433.33333333333,"denominator":300,"metric_version":"metrics-2"})).collect::<Vec<_>>());
        real.save_replay(&r).unwrap();
    }
    let mut reports = vec![];
    for mode in ["1v1", "2v2", "3v3", "All"] {
        let manifest = real.analytics_context(Some("p"), mode).unwrap();
        let s = CoachService {
            manifest,
            replay: replay(),
            memory: json!([{"name":"profile.md","content":"Practice recovery. ".repeat(200)}]),
        };
        let ctx = s.build_context(
            &json!({"player_id":"p","player_name":"Player","chat_mode":mode}),
            Some("m"),
            None,
        );
        reports.push(json!({"library_matches":60,"mode":mode,"context_chars":ctx.text.chars().count(),"library_chars":s.library_section(Some("p"),Some("m"),mode).chars().count(),"has_match_header":ctx.text.contains("== MATCH =="),"event_ids":ctx.event_ids.len(),"truncated":ctx.text.contains("Context budget reached:")}));
        if mode == "All" {
            assert!(ctx.text.contains("Context budget reached:"));
            assert!(ctx.event_ids.is_empty());
            assert!(!ctx.text.contains("== MATCH =="));
        }
    }
    println!("REVIEW_CONTEXT_MEASUREMENTS {}", json!(reports));
}
